action_details.action_postfix:
// Physical nexus established - filing required
true result.me_has_nexus xdef
"Maine filing required: Physical presence (office, employees, or property in state)" job.audit_trail swap addto

// Economic nexus established per factor presence standards - filing required
true result.me_has_nexus xdef
"Maine filing required: Economic nexus (factor presence: $250K property, $250K payroll, $500K sales, or 25% factor)" job.audit_trail swap addto

// Calculate Maine state additions
0.0 /me_additions xdef

// Common Maine additions:
// - IRC 199A qualified business income deduction addback (ME doesn't conform)
// - Depreciation differences
// - Safe harbor lease deductions

result.me_section_199a_addback 0.0 ne
{
  me_additions result.me_section_199a_addback add /me_additions xdef
} if

me_additions result.me_state_additions xdef

// Calculate Maine state subtractions
0.0 /me_subtractions xdef

// Common Maine subtractions:
// - Federal bond interest (exempt from ME tax)
// - Maine municipal bond interest
// - Dividends from subsidiaries (95% deduction)
// - Maine NOL deduction

result.me_us_interest_income 0.0 ne
{
  me_subtractions result.me_us_interest_income add /me_subtractions xdef
} if

result.me_municipal_interest 0.0 ne
{
  me_subtractions result.me_municipal_interest add /me_subtractions xdef
} if

me_subtractions result.me_state_subtractions xdef

"Maine additions: $" result.me_state_additions cvs strconcat ", subtractions: $" strconcat result.me_state_subtractions cvs strconcat job.audit_trail swap addto

// Calculate Maine taxable income
// Federal taxable income apportioned to ME + additions - subtractions
result.me_apportioned_income
result.me_state_additions add
result.me_state_subtractions sub
0.0 max
result.me_taxable_income xdef

// Calculate Maine tax using graduated rates
0.0 /me_tax xdef

// Tier 1: 3.5% on first $350,000
result.me_taxable_income 350000.0 min result.me_corp_tax_rate_tier1 mul
/me_tier1_tax xdef
me_tax me_tier1_tax add /me_tax xdef

// Tier 2: 7.5% on $350,001 to $1,050,000
result.me_taxable_income 350000.0 >
{
  result.me_taxable_income 1050000.0 min 350000.0 sub
  result.me_corp_tax_rate_tier2 mul
  /me_tier2_tax xdef
  me_tax me_tier2_tax add /me_tax xdef
} if

// Tier 3: 8.3% on $1,050,001 to $3,500,000
result.me_taxable_income 1050000.0 >
{
  result.me_taxable_income 3500000.0 min 1050000.0 sub
  result.me_corp_tax_rate_tier3 mul
  /me_tier3_tax xdef
  me_tax me_tier3_tax add /me_tax xdef
} if

// Tier 4: 8.93% on income over $3,500,000
result.me_taxable_income 3500000.0 >
{
  result.me_taxable_income 3500000.0 sub
  result.me_corp_tax_rate_tier4 mul
  /me_tier4_tax xdef
  me_tax me_tier4_tax add /me_tax xdef
} if

// Subtract Maine state credits (Pine Tree Zone, R&D, employment credits, etc.)
me_tax result.me_state_credits sub 0.0 max
result.me_tax_liability xdef

// Calculate refund or amount owed
result.me_estimated_payments result.me_tax_liability sub
result.me_refund_or_owed xdef

"Maine taxable income: $" result.me_taxable_income cvs strconcat job.audit_trail swap addto
"Maine tax liability (graduated rates 3.5%-8.93%): $" result.me_tax_liability cvs strconcat job.audit_trail swap addto
